from dataclasses import dataclass

import pytest

DEFAULTS: dict[str, str] = {"mode": "fast", "level": "3"}


@dataclass
class LengthMismatch(Exception):
    keys: int
    values: int


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] = values[i] on the defaults mode=fast, level=3.

    Returns the resulting values in the order mode, level, then any other
    keys in the order they first appear in `keys`. If a key repeats, the
    last value wins but its position stays at its first appearance.
    Raises LengthMismatch if len(keys) != len(values).
    """
    if len(keys) != len(values):
        raise LengthMismatch(len(keys), len(values))
    merged: dict[str, str] = dict(DEFAULTS)
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_no_overrides_gives_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["9"]) == ["fast", "9"]


def test_override_both_in_any_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["z", "a", "mode"], ["1", "2", "slow"]) == [
        "slow",
        "3",
        "1",
        "2",
    ]


def test_extra_keys_with_both_overrides() -> None:
    keys = ["b", "level", "a", "mode"]
    vals = ["x", "7", "y", "m"]
    assert settings(keys, vals) == ["m", "7", "x", "y"]


def test_duplicate_key_last_wins_first_position() -> None:
    assert settings(["a", "b", "a"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_default_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_empty_string_values_preserved() -> None:
    assert settings(["mode", "x"], ["", ""]) == ["", "3", ""]


def test_does_not_mutate_inputs_or_defaults() -> None:
    keys = ["mode"]
    vals = ["slow"]
    settings(keys, vals)
    assert keys == ["mode"]
    assert vals == ["slow"]
    assert DEFAULTS == {"mode": "fast", "level": "3"}
    assert settings([], []) == ["fast", "3"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(LengthMismatch):
        settings(["a", "b"], ["1"])
    with pytest.raises(LengthMismatch):
        settings([], ["1"])

